-- SEC-100 remediation (b): the application records the time of the last maintenance run and of
-- the last run in which all three jobs succeeded (DATA_MODEL.md sections 6.19 and 21.11).
-- Additive only: one new table with a single row, one check constraint. No existing row changes.
-- No personal data. There is no down migration; the manual undo is in DATA_MODEL.md section 17.

-- CreateTable (generated by Prisma)
CREATE TABLE "MaintenanceStatus" (
    "id" INTEGER NOT NULL,
    "lastSuccessAt" TIMESTAMPTZ(3),
    "lastRunAt" TIMESTAMPTZ(3),
    "lastRunOk" BOOLEAN,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "MaintenanceStatus_pkey" PRIMARY KEY ("id")
);

-- Hand-written below: Prisma cannot express these (DATA_MODEL.md section 13).

-- Single row, as for "MarketplaceSettings".
ALTER TABLE "MaintenanceStatus" ADD CONSTRAINT "MaintenanceStatus_id_check" CHECK ("id" = 1);

-- The single row. Every time is NULL, so a fresh deployment reads as "never ran", not as a failure.
INSERT INTO "MaintenanceStatus" ("id", "lastSuccessAt", "lastRunAt", "lastRunOk", "updatedAt")
VALUES (1, NULL, NULL, NULL, CURRENT_TIMESTAMP);
